class Celsius:
    def __init__(self, temp):
        self._temp = temp
    @property
    def temp(self):
        return self._temp
    @temp.setter
    def temp(self, value):
        if value < -273.15:
            raise ValueError("Below absolute zero")
        self._temp = value
c = Celsius(25)
c.temp = -300
print(c.temp)
```

