class Num:
    def __init__(self, n): self.n = n
    def __add__(self, other):
        if isinstance(other, Num):
            return Num(self.n + other.n)
        return NotImplemented
    def __repr__(self): return f"Num({self.n})"
result = Num(3) + Num(4)
print(result)
print(type(result).__name__)
```

